            { number: 956, state: 'open', labels: [{ name: 'pr_approved' }, { name: 'ai_validating' }] },
            'gh-952', 'passed', true, 'CONTENT');
        assert.deepEqual(calls.map(function(c) { return c[0]; }), ['comment'],
